steps.script:
var main = tree.root.get_node("Main")
DebugLogger._flush_buffer()
var lf = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var lines := 0
while lf != null and not lf.eof_reached():
	lf.get_line()
	lines += 1
main.set_meta("b1_log_mark", lines)
var st = GameState.state
for puid in st.units:
	if puid == "U_KOMMANDOS_H" or puid == "MIR_U_KOMMANDOS_H" or puid == "MIR_U_KAPTIN_BADRUKK_A":
		continue
	st.units[puid].status = GameStateData.UnitStatus.IN_RESERVES
	for pm in st.units[puid].models:
		pm.position = null
var pk: Array = st.units.MIR_U_KOMMANDOS_H.models
var pcx := 0.0
for i in range(3, 10):
	pcx += float(pk[i].position.x)
pcx /= 7.0
var pcy := float(pk[3].position.y)
for i in range(10):
	pk[i].position = {"x": pcx + (float(i % 5) - 2.0) * 60.0, "y": pcy + (float(i / 5) - 0.5) * 60.0}
var km: Array = st.units.U_KOMMANDOS_H.models
var cx := 0.0
for i in range(3, 10):
	cx += float(km[i].position.x)
cx /= 7.0
var cy := float(km[3].position.y)
for i in range(10):
	km[i].position = {"x": cx + (float(i % 5) - 2.0) * 60.0, "y": cy + (float(i / 5) - 0.5) * 60.0}
var start := {}
for m in km:
	start[str(m.id)] = [float(m.position.x), float(m.position.y)]
main.set_meta("b1_start", start)
GameState.set_active_player(2)
var snap = GameState.create_snapshot(false)
var unit = snap.units.U_KOMMANDOS_H
var c: Vector2 = AIDecisionMaker._get_unit_centroid(unit)
var target: Vector2 = AIDecisionMaker._find_best_scout_objective(unit, AIDecisionMaker._get_objectives(snap), AIDecisionMaker._get_enemy_units(snap, 2), AIDecisionMaker._get_units_for_player(snap, 2), 2, snap)
var dir := (target - c).normalized()
var blk := c + dir * 13.25 * 40.0
st.units.MIR_U_KAPTIN_BADRUKK_A.models[0].position = {"x": blk.x, "y": blk.y}
main._recreate_unit_visuals()
return "kommandos centroid (%.0f,%.0f) toward (%.0f,%.0f); blocker at (%.0f,%.0f)" % [c.x, c.y, target.x, target.y, blk.x, blk.y]

var pi = PhaseManager.get_current_phase_instance()
var n = 0
while pi.has_method("get_pending_stratagem_window") and not pi.get_pending_stratagem_window().is_empty() and n < 6:
	var w = pi.get_pending_stratagem_window()
	pi.execute_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(pi.get_pending_stratagem_window_decider()), "window_id": w.get("window_id", "")})
	n += 1
return n

var main = tree.root.get_node("Main")
var t := str(main._get_phase_tooltip_text(GameStateData.Phase.SCOUT))
return t.contains("more than 8\"") and not t.contains("9\"")

var main = tree.root.get_node("Main")
var d: Dictionary = main._ai_suggestion_panel._decision
var dests: Dictionary = d.get("_ai_scout_destinations", {})
var b = GameState.state.units.MIR_U_KAPTIN_BADRUKK_A.models[0]
var bp := Vector2(float(b.position.x), float(b.position.y))
var best := INF
for mid in dests:
	var v := Vector2(float(dests[mid][0]), float(dests[mid][1]))
	best = minf(best, v.distance_to(bp) / 40.0 - (32.0 / 2.0) / 25.4 - (float(b.base_mm) / 2.0) / 25.4)
main.set_meta("b1_planned_min", best)
return snappedf(best, 0.01)

var c := 0
var k := 0
for e in AIPlayer.get_action_log():
	if str(e.get("action_type", "")) == "CONFIRM_SCOUT_MOVE":
		c += 1
	if str(e.get("description", "")).contains("skipped") or str(e.get("action_type", "")) == "SKIP_SCOUT_MOVE":
		k += 1
return "confirm=%d skip=%d" % [c, k]

var main = tree.root.get_node("Main")
var b = GameState.state.units.MIR_U_KAPTIN_BADRUKK_A.models[0]
var bp := Vector2(float(b.position.x), float(b.position.y))
var start: Dictionary = main.get_meta("b1_start")
var best := INF
var moved := 0
for m in GameState.state.units.U_KOMMANDOS_H.models:
	var p := Vector2(float(m.position.x), float(m.position.y))
	var s: Array = start[str(m.id)]
	if p.distance_to(Vector2(s[0], s[1])) > 20.0:
		moved += 1
	best = minf(best, p.distance_to(bp) / 40.0 - (float(m.base_mm) / 2.0) / 25.4 - (float(b.base_mm) / 2.0) / 25.4)
main.set_meta("b1_after_min", best)
main.set_meta("b1_moved", moved)
print("[B1-SCENARIO] Kommandos moved %d/10 models; closest base-to-base gap to the enemy %.2f in" % [moved, best])
return snappedf(best, 0.01)

var main = tree.root.get_node("Main")
DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var mark := int(main.get_meta("b1_log_mark", 0))
var i := 0
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	i += 1
	if i > mark and l.contains("[ERROR"):
		n += 1
		print("[B1-SCENARIO] debug-log ERROR: ", l)
return n
